class Solution:
    def isConvex(self, points: List[List[int]]) -> bool:
        n = len(points)
        pos = neg = False
        for i in range(n):
            px, py = points[i - 1]
            cx, cy = points[i]
            nx, ny = points[(i + 1) % n]
            cross = (cx - px) * (ny - cy) - (cy - py) * (nx - cx)
            if cross > 0:
                pos = True
            elif cross < 0:
                neg = True
            if pos and neg:
                return False
        return True

