class Solution {
public:
    bool isConvex(vector<vector<int>>& points) {
        int n = points.size();
        bool pos = false, neg = false;
        for (int i = 0; i < n; ++i) {
            auto& p = points[(i + n - 1) % n];
            auto& c = points[i];
            auto& q = points[(i + 1) % n];
            long long cross = (long long)(c[0] - p[0]) * (q[1] - c[1])
                            - (long long)(c[1] - p[1]) * (q[0] - c[0]);
            if (cross > 0) pos = true;
            else if (cross < 0) neg = true;
            if (pos && neg) return false;
        }
        return true;
    }
};

