class Solution {
public:
    bool isConvex(vector<vector<int>>& points) {
        int n = points.size();
        double total = 0.0;
        for (int i = 0; i < n; ++i) {
            auto& p = points[(i + n - 1) % n];
            auto& c = points[i];
            auto& q = points[(i + 1) % n];
            double v1x = c[0] - p[0], v1y = c[1] - p[1];
            double v2x = q[0] - c[0], v2y = q[1] - c[1];
            total += atan2(v1x * v2y - v1y * v2x, v1x * v2x + v1y * v2y);
        }
        return fabs(fabs(total) - 2 * M_PI) < 1e-9;
    }
};

